{
  "ingredients": [
    {
      "name": "potatoes",
      "quantity": "4 medium"
    },
    {
      "name": "onion",
      "quantity": "1"
    },
    {
      "name": "olive oil",
      "quantity": "plenty"
    },
    {
      "name": "eggs",
      "quantity": "6"
    },
    {
      "name": "salt",
      "quantity": "to taste"
    }
  ],
  "steps": [
    "Peel and slice 4 medium potatoes thinly.",
    "Chop 1 onion.",
    "Fry both in plenty of olive oil for 15 minutes over medium heat.",
    "Beat 6 eggs in a large bowl with salt.",
    "Mix the potatoes and onion with the eggs and let stand 5 minutes.",
    "Pour into a hot pan with a little oil.",
    "Cook 4 minutes per side."
  ]
}
